=head2 Google::Cloud::Asset::V1::AssetService::GcsDestination

A Cloud Storage location.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->uri() >> / C<< $msg->uri($value) >>

Type: C<String>

The URI of the Cloud Storage object. It's the same URI that is used by
gsutil. Example: "gs://bucket_name/object_name". See [Viewing and
Editing Object
Metadata](https://cloud.google.com/storage/docs/viewing-editing-metadata)
for more information.

If the specified Cloud Storage object already exists and there is no
[hold](https://cloud.google.com/storage/docs/object-holds), it will be
overwritten with the exported result.

=item * C<< $msg->uri_prefix() >> / C<< $msg->uri_prefix($value) >>

Type: C<String>

The URI prefix of all generated Cloud Storage objects. Example:
"gs://bucket_name/object_name_prefix". Each object URI is in format:
"gs://bucket_name/object_name_prefix/<asset type>/<shard number> and only
contains assets for that type. <shard number> starts from 0. Example:
"gs://bucket_name/object_name_prefix/compute.googleapis.com/Disk/0" is
the first shard of output objects containing all
compute.googleapis.com/Disk assets. An INVALID_ARGUMENT error will be
returned if file with the same name "gs://bucket_name/object_name_prefix"
already exists.

=back

=head2 Google::Cloud::Asset::V1::AssetService::BigQueryDestination

A BigQuery destination for exporting assets to.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->dataset() >> / C<< $msg->dataset($value) >>

Type: C<String>

Required. The BigQuery dataset in format
"projects/projectId/datasets/datasetId", to which the snapshot result
should be exported. If this dataset does not exist, the export call returns
an INVALID_ARGUMENT error. Setting the `contentType` for `exportAssets`
determines the
[schema](/asset-inventory/docs/exporting-to-bigquery#bigquery-schema)
of the BigQuery table. Setting `separateTablesPerAssetType` to `TRUE` also
influences the schema.

=item * C<< $msg->table() >> / C<< $msg->table($value) >>

Type: C<String>

Required. The BigQuery table to which the snapshot result should be
written. If this table does not exist, a new table with the given name
will be created.

=item * C<< $msg->force() >> / C<< $msg->force($value) >>

Type: C<Bool>

If the destination table already exists and this flag is `TRUE`, the
table will be overwritten by the contents of assets snapshot. If the flag
is `FALSE` or unset and the destination table already exists, the export
call returns an INVALID_ARGUMEMT error.

=item * C<< $msg->partition_spec() >> / C<< $msg->partition_spec($value) >>

Type: C<Message> (L<Google::Cloud::Asset::V1::AssetService::PartitionSpec>)

[partition_spec] determines whether to export to partitioned table(s) and
how to partition the data.

If [partition_spec] is unset or [partition_spec.partition_key] is unset or
`PARTITION_KEY_UNSPECIFIED`, the snapshot results will be exported to
non-partitioned table(s). [force] will decide whether to overwrite existing
table(s).

If [partition_spec] is specified. First, the snapshot results will be
written to partitioned table(s) with two additional timestamp columns,
readTime and requestTime, one of which will be the partition key. Secondly,
in the case when any destination table already exists, it will first try to
update existing table's schema as necessary by appending additional
columns. Then, if [force] is `TRUE`, the corresponding partition will be
overwritten by the snapshot results (data in different partitions will
remain intact); if [force] is unset or `FALSE`, it will append the data. An
error will be returned if the schema update or data appension fails.

=item * C<< $msg->separate_tables_per_asset_type() >> / C<< $msg->separate_tables_per_asset_type($value) >>

Type: C<Bool>

If this flag is `TRUE`, the snapshot results will be written to one or
multiple tables, each of which contains results of one asset type. The
[force] and [partition_spec] fields will apply to each of them.

Field [table] will be concatenated with "_" and the asset type names (see
https://cloud.google.com/asset-inventory/docs/supported-asset-types for
supported asset types) to construct per-asset-type table names, in which
all non-alphanumeric characters like "." and "/" will be substituted by
"_". Example: if field [table] is "mytable" and snapshot results
contain "storage.googleapis.com/Bucket" assets, the corresponding table
name will be "mytable_storage_googleapis_com_Bucket". If any of these
tables does not exist, a new table with the concatenated name will be
created.

When [content_type] in the ExportAssetsRequest is `RESOURCE`, the schema of
each table will include RECORD-type columns mapped to the nested fields in
the Asset.resource.data field of that asset type (up to the 15 nested level
BigQuery supports
(https://cloud.google.com/bigquery/docs/nested-repeated#limitations)). The
fields in >15 nested levels will be stored in JSON format string as a child
column of its parent RECORD column.

If error occurs when exporting to any table, the whole export call will
return an error but the export results that already succeed will persist.
Example: if exporting to table_type_A succeeds when exporting to
table_type_B fails during one export call, the results in table_type_A will
persist and there will not be partial results persisting in a table.

=back

