Optional. A SQL statement that's compatible with [BigQuery
SQL](https://cloud.google.com/bigquery/docs/introduction-sql).

=item * C<< $msg->job_reference() >> / C<< $msg->job_reference($value) >>

Type: C<String>

Optional. Reference to the query job, which is from the
`QueryAssetsResponse` of previous `QueryAssets` call.

=item * C<< $msg->page_size() >> / C<< $msg->page_size($value) >>

Type: C<Int32>

Optional. The maximum number of rows to return in the results. Responses
are limited to 10 MB and 1000 rows.

By default, the maximum row count is 1000. When the byte or row count limit
is reached, the rest of the query results will be paginated.

The field will be ignored when [output_config] is specified.

=item * C<< $msg->page_token() >> / C<< $msg->page_token($value) >>

Type: C<String>

Optional. A page token received from previous `QueryAssets`.

The field will be ignored when [output_config] is specified.

=item * C<< $msg->timeout() >> / C<< $msg->timeout($value) >>

Type: C<Message> (L<Google::Protobuf::Duration::Duration>)

Optional. Specifies the maximum amount of time that the client is willing
to wait for the query to complete. By default, this limit is 5 min for the
first query, and 1 minute for the following queries. If the query is
complete, the `done` field in the `QueryAssetsResponse` is true, otherwise
false.

Like BigQuery [jobs.query
API](https://cloud.google.com/bigquery/docs/reference/rest/v2/jobs/query#queryrequest)
The call is not guaranteed to wait for the specified timeout; it typically
returns after around 200 seconds (200,000 milliseconds), even if the query
is not complete.

The field will be ignored when [output_config] is specified.

=item * C<< $msg->read_time_window() >> / C<< $msg->read_time_window($value) >>

Type: C<Message> (L<Google::Cloud::Asset::V1::Assets::TimeWindow>)

Optional. [start_time] is required. [start_time] must be less than
[end_time] Defaults [end_time] to now if [start_time] is set and
[end_time] isn't. Maximum permitted time range is 7 days.

=item * C<< $msg->read_time() >> / C<< $msg->read_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Optional. Queries cloud assets as they appeared at the specified point in
time.

=item * C<< $msg->output_config() >> / C<< $msg->output_config($value) >>

Type: C<Message> (L<Google::Cloud::Asset::V1::AssetService::QueryAssetsOutputConfig>)

Optional. Destination where the query results will be saved.

When this field is specified, the query results won't be saved in the
[QueryAssetsResponse.query_result]. Instead
[QueryAssetsResponse.output_config] will be set.

Meanwhile, [QueryAssetsResponse.job_reference] will be set and can be used
to check the status of the query job when passed to a following
[QueryAssets] API call.

=back

=head2 Google::Cloud::Asset::V1::AssetService::QueryAssetsResponse

QueryAssets response.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->job_reference() >> / C<< $msg->job_reference($value) >>

Type: C<String>

Reference to a query job.

=item * C<< $msg->done() >> / C<< $msg->done($value) >>

Type: C<Bool>

The query response, which can be either an `error` or a valid `response`.

If `done` == `false` and the query result is being saved in an output, the
output_config field will be set.
If `done` == `true`, exactly one of
`error`, `query_result` or `output_config` will be set.
[done] is unset unless the [QueryAssetsResponse] contains a
[QueryAssetsResponse.job_reference].

=item * C<< $msg->error() >> / C<< $msg->error($value) >>

Type: C<Message> (L<Google::Rpc::Status::Status>)

Error status.

=item * C<< $msg->query_result() >> / C<< $msg->query_result($value) >>

Type: C<Message> (L<Google::Cloud::Asset::V1::AssetService::QueryResult>)

Result of the query.

=item * C<< $msg->output_config() >> / C<< $msg->output_config($value) >>

Type: C<Message> (L<Google::Cloud::Asset::V1::AssetService::QueryAssetsOutputConfig>)

Output configuration, which indicates that instead of being returned in
an API response on the fly, the query result will be saved in a specific
output.

=back

=head2 Google::Cloud::Asset::V1::AssetService::QueryResult

Execution results of the query.

The result is formatted as rows represented by BigQuery compatible [schema].
When pagination is necessary, it will contains the page token to retrieve
the results of following pages.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->rows() >> / C<< $msg->rows($value) >>

Type: C<Message> (L<Google::Protobuf::Struct::Struct>)

Each row hold a query result in the format of `Struct`.

=item * C<< $msg->schema() >> / C<< $msg->schema($value) >>

Type: C<Message> (L<Google::Cloud::Asset::V1::AssetService::TableSchema>)

Describes the format of the [rows].

=item * C<< $msg->next_page_token() >> / C<< $msg->next_page_token($value) >>

Type: C<String>

Token to retrieve the next page of the results.

=item * C<< $msg->total_rows() >> / C<< $msg->total_rows($value) >>

Type: C<Int64>

Total rows of the whole query results.

=back

=head2 Google::Cloud::Asset::V1::AssetService::TableSchema

BigQuery Compatible table schema.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->fields() >> / C<< $msg->fields($value) >>

Type: C<Message> (L<Google::Cloud::Asset::V1::AssetService::TableFieldSchema>)

Describes the fields in a table.

=back

=head2 Google::Cloud::Asset::V1::AssetService::TableFieldSchema

A field in TableSchema.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->field() >> / C<< $msg->field($value) >>

Type: C<String>

The field name. The name must contain only letters (a-z, A-Z),
numbers (0-9), or underscores (_), and must start with a letter or
underscore. The maximum length is 128 characters.

=item * C<< $msg->type() >> / C<< $msg->type($value) >>

Type: C<String>

The field data type. Possible values include
* STRING
* BYTES
* INTEGER
* FLOAT
* BOOLEAN
* TIMESTAMP
* DATE
* TIME
* DATETIME
* GEOGRAPHY,
* NUMERIC,
* BIGNUMERIC,
* RECORD
(where RECORD indicates that the field contains a nested schema).

=item * C<< $msg->mode() >> / C<< $msg->mode($value) >>

Type: C<String>

The field mode. Possible values include NULLABLE, REQUIRED and
REPEATED. The default value is NULLABLE.

=item * C<< $msg->fields() >> / C<< $msg->fields($value) >>

Type: C<Message> (L<Google::Cloud::Asset::V1::AssetService::TableFieldSchema>)

Describes the nested schema fields if the type property is set
to RECORD.

=back

=head2 Google::Cloud::Asset::V1::AssetService::BatchGetEffectiveIamPoliciesRequest

A request message for
[AssetService.BatchGetEffectiveIamPolicies][google.cloud.asset.v1.AssetService.BatchGetEffectiveIamPolicies].

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->scope() >> / C<< $msg->scope($value) >>

Type: C<String>

Required. Only IAM policies on or below the scope will be returned.

This can only be an organization number (such as "organizations/123"), a
folder number (such as "folders/123"), a project ID (such as
"projects/my-project-id"), or a project number (such as "projects/12345").

To know how to get organization ID, visit [here
](https://cloud.google.com/resource-manager/docs/creating-managing-organization#retrieving_your_organization_id).

To know how to get folder or project ID, visit [here
](https://cloud.google.com/resource-manager/docs/creating-managing-folders#viewing_or_listing_folders_and_projects).

=item * C<< $msg->names() >> / C<< $msg->names($value) >>

Type: C<String>

Required. The names refer to the [full_resource_names]
(https://cloud.google.com/asset-inventory/docs/resource-name-format)
of the asset types [supported by search
APIs](https://cloud.google.com/asset-inventory/docs/supported-asset-types).
A maximum of 20 resources' effective policies can be retrieved in a batch.

=back

=head2 Google::Cloud::Asset::V1::AssetService::BatchGetEffectiveIamPoliciesResponse

A response message for
[AssetService.BatchGetEffectiveIamPolicies][google.cloud.asset.v1.AssetService.BatchGetEffectiveIamPolicies].

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->policy_results() >> / C<< $msg->policy_results($value) >>

Type: C<Message> (L<Google::Cloud::Asset::V1::AssetService::BatchGetEffectiveIamPoliciesResponse::EffectiveIamPolicy>)

The effective policies for a batch of resources. Note that the results
order is the same as the order of
[BatchGetEffectiveIamPoliciesRequest.names][google.cloud.asset.v1.BatchGetEffectiveIamPoliciesRequest.names].
When a resource does not have any effective IAM policies, its corresponding
policy_result will contain empty
[EffectiveIamPolicy.policies][google.cloud.asset.v1.BatchGetEffectiveIamPoliciesResponse.EffectiveIamPolicy.policies].

=back

=head2 Google::Cloud::Asset::V1::AssetService::AnalyzerOrgPolicy

This organization policy message is a modified version of the one defined in
the Organization Policy system. This message contains several fields defined
in the original organization policy with some new fields for analysis
purpose.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->attached_resource() >> / C<< $msg->attached_resource($value) >>

Type: C<String>

The [full resource name]
(https://cloud.google.com/asset-inventory/docs/resource-name-format) of
an organization/folder/project resource where this organization policy is
set.

Notice that some type of constraints are defined with default policy. This
field will be empty for them.

=item * C<< $msg->applied_resource() >> / C<< $msg->applied_resource($value) >>

Type: C<String>

The [full resource name]
(https://cloud.google.com/asset-inventory/docs/resource-name-format) of
an organization/folder/project resource where this organization policy
applies to.

For any user defined org policies, this field has the same value as
the [attached_resource] field. Only for default policy, this field has
the different value.

=item * C<< $msg->rules() >> / C<< $msg->rules($value) >>

Type: C<Message> (L<Google::Cloud::Asset::V1::AssetService::AnalyzerOrgPolicy::Rule>)

List of rules for this organization policy.

=item * C<< $msg->inherit_from_parent() >> / C<< $msg->inherit_from_parent($value) >>

Type: C<Bool>

If `inherit_from_parent` is true, Rules set higher up in the
hierarchy (up to the closest root) are inherited and present in the
effective policy. If it is false, then no rules are inherited, and this
policy becomes the effective root for evaluation.

=item * C<< $msg->reset() >> / C<< $msg->reset($value) >>

Type: C<Bool>

Ignores policies set above this resource and restores the default behavior
of the constraint at this resource.
This field can be set in policies for either list or boolean
constraints. If set, `rules` must be empty and `inherit_from_parent`
must be set to false.

=back

=head2 Google::Cloud::Asset::V1::AssetService::AnalyzerOrgPolicyConstraint

The organization policy constraint definition.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->google_defined_constraint() >> / C<< $msg->google_defined_constraint($value) >>

Type: C<Message> (L<Google::Cloud::Asset::V1::AssetService::AnalyzerOrgPolicyConstraint::Constraint>)

The definition of the canned constraint defined by Google.

=item * C<< $msg->custom_constraint() >> / C<< $msg->custom_constraint($value) >>

Type: C<Message> (L<Google::Cloud::Asset::V1::AssetService::AnalyzerOrgPolicyConstraint::CustomConstraint>)

The definition of the custom constraint.

=back

=head2 Google::Cloud::Asset::V1::AssetService::AnalyzeOrgPoliciesRequest

A request message for
[AssetService.AnalyzeOrgPolicies][google.cloud.asset.v1.AssetService.AnalyzeOrgPolicies].

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->scope() >> / C<< $msg->scope($value) >>

Type: C<String>

Required. The organization to scope the request. Only organization
policies within the scope will be analyzed.

* organizations/{ORGANIZATION_NUMBER} (e.g., "organizations/123456")

=item * C<< $msg->constraint() >> / C<< $msg->constraint($value) >>

Type: C<String>

Required. The name of the constraint to analyze organization policies for.
The response only contains analyzed organization policies for the provided
constraint.

=item * C<< $msg->filter() >> / C<< $msg->filter($value) >>

Type: C<String>

The expression to filter
[AnalyzeOrgPoliciesResponse.org_policy_results][google.cloud.asset.v1.AnalyzeOrgPoliciesResponse.org_policy_results].
Filtering is currently available for bare literal values and the following
fields:
* consolidated_policy.attached_resource
* consolidated_policy.rules.enforce

When filtering by a specific field, the only supported operator is `=`.
For example, filtering by
consolidated_policy.attached_resource="//cloudresourcemanager.googleapis.com/folders/001"
will return all the Organization Policy results attached to "folders/001".

=item * C<< $msg->page_size() >> / C<< $msg->page_size($value) >>

Type: C<Int32>

The maximum number of items to return per page. If unspecified,
[AnalyzeOrgPoliciesResponse.org_policy_results][google.cloud.asset.v1.AnalyzeOrgPoliciesResponse.org_policy_results]
will contain 20 items with a maximum of 200.

=item * C<< $msg->page_token() >> / C<< $msg->page_token($value) >>

Type: C<String>

The pagination token to retrieve the next page.

=back

